package platform.contentapi.management;

import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import platform.contentapi.execution.*;
import tools.jackson.databind.node.ObjectNode;
import static org.assertj.core.api.Assertions.*;

/** Synthetic SQL evidence only. Native qualification/process cleanup is covered separately in RssContentIT. */
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class ContentFinalizationIT extends RssFetchFixtures {
    RssContentTestSupport.Fence fence;
    @Override ObjectNode content(){var n=super.content();n.withArray("retainedSilverArtifactIds").removeAll();return n;}
    void seeded(){ready();fence=RssContentTestSupport.seed(jdbc,workers,guard,owner);}
    UUID finish(){return RssContentTestSupport.finish(jdbc,workers,guard,fence);}
    void occupied(){assertThat(jdbc.queryForObject("SELECT active_attempt_id FROM ddip_management.coordinator",UUID.class)).isEqualTo(owner.attemptId());assertThat(jdbc.queryForObject("SELECT count(*) FROM ddip_management.artifacts WHERE kind='CONTENT'",Integer.class)).isZero();assertThat(jdbc.queryForObject("SELECT count(*) FROM ddip_management.audit_events WHERE action='RUN_SUCCEEDED'",Integer.class)).isZero();}
    @Test void terminalTransactionAndDuplicateInvocation(){seeded();UUID artifact=finish();assertThat(jdbc.queryForObject("SELECT result_artifact_id FROM ddip_management.runs WHERE run_id=?",UUID.class,owner.runId())).isEqualTo(artifact);assertThat(jdbc.queryForObject("SELECT state FROM ddip_management.attempts WHERE attempt_id=?",String.class,owner.attemptId())).isEqualTo("SUCCEEDED");assertThat(jdbc.queryForObject("SELECT active_attempt_id FROM ddip_management.coordinator",UUID.class)).isNull();assertThatThrownBy(this::finish).hasMessage("OWNERSHIP_LOST");assertThat(jdbc.queryForObject("SELECT count(*) FROM ddip_management.audit_events WHERE action='RUN_SUCCEEDED'",Integer.class)).isEqualTo(1);}
    @ParameterizedTest @ValueSource(strings={"coordinator","worker","attempt","run","stage","guard","cancel","retry","unknownStage","extraStage","substitutedGold","substitutedReference","substitutedDependency"}) void preconditionsFailClosed(String point){seeded();switch(point){
        case "coordinator"->jdbc.update("UPDATE ddip_management.coordinator SET row_version=row_version+1");
        case "worker"->jdbc.update("UPDATE ddip_management.worker_instances SET row_version=row_version+1");
        case "attempt"->jdbc.update("UPDATE ddip_management.attempts SET row_version=row_version+1 WHERE attempt_id=?",owner.attemptId());
        case "run"->jdbc.update("UPDATE ddip_management.runs SET row_version=row_version+1 WHERE run_id=?",owner.runId());
        case "stage"->jdbc.update("UPDATE ddip_management.stage_invocations SET row_version=row_version+1 WHERE stage='VERIFY_RESULT'");
        case "guard"->guard.close();
        case "cancel","retry"->{byte[] raw=SourceJson.canonical(SourceJson.object());jdbc.update("INSERT INTO ddip_management.controls(control_id,run_id,type,idempotency_key,normalized_request,request_sha256,expected_version,state,requester) VALUES (?,?,?,'pending',?,?,2,'REQUESTED','local-operator')",UUID.randomUUID(),owner.runId(),point.toUpperCase(Locale.ROOT),raw,SourceJson.sha(raw));}
        case "unknownStage"->jdbc.update("UPDATE ddip_management.stage_invocations SET state='UNKNOWN',row_version=row_version+1 WHERE stage='VERIFY_RESULT'");
        case "extraStage"->jdbc.update("INSERT INTO ddip_management.stage_invocations(attempt_id,stage,item_ordinal,checkpoint_id,state,input_evidence_sha256) VALUES (?,'CHECK_INPUTS',1,?,'INTENT',?)",owner.attemptId(),UUID.randomUUID(),"a".repeat(64));
        case "substitutedGold"->((ObjectNode)fence.gold()).put("artifactId",UUID.randomUUID().toString());
        case "substitutedReference"->((ObjectNode)fence.reference()).put("artifactId",UUID.randomUUID().toString());
        case "substitutedDependency"->{var e=(ObjectNode)SourceJson.parse(fence.artifact());((ObjectNode)e.get("inputs").get(0)).put("artifactId",UUID.randomUUID().toString());fence=new RssContentTestSupport.Fence(fence.stage(),fence.frozen(),fence.gold(),fence.reference(),SourceJson.canonical(e));}
    }assertThatThrownBy(this::finish).isInstanceOf(RuntimeException.class);occupied();}
    @ParameterizedTest @ValueSource(strings={"artifacts","artifact_dependencies","stage_artifacts","stage_invocations","attempts","runs","coordinator","audit_events"}) void everyMutationRollsBack(String table){seeded();var before=jdbc.queryForMap("SELECT * FROM ddip_management.coordinator");jdbc.execute("CREATE FUNCTION ddip_management.d5_fault() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION USING MESSAGE='PRIVATE',ERRCODE='23514'; END $$");jdbc.execute("CREATE TRIGGER d5_fault BEFORE INSERT OR UPDATE ON ddip_management."+table+" FOR EACH ROW "+(table.equals("audit_events")?"WHEN (NEW.action='RUN_SUCCEEDED') ":"")+"EXECUTE FUNCTION ddip_management.d5_fault()");assertThatThrownBy(this::finish).hasMessage("STATE_CONFLICT");occupied();assertThat(jdbc.queryForMap("SELECT * FROM ddip_management.coordinator")).isEqualTo(before);assertThat(jdbc.queryForObject("SELECT state FROM ddip_management.stage_invocations WHERE stage='VERIFY_RESULT'",String.class)).isEqualTo("RUNNING");}
    @Test void ambiguousCleanupAndDuplicateAuthorizationRemainOccupied(){seeded();assertThatThrownBy(()->RssContentTestSupport.authorizeAgain(workers,guard,fence)).hasMessage("OWNERSHIP_LOST");occupied();workers=WorkerTestSupport.enabled(jdbc,tx,INSTALL);RssContentTestSupport.ambiguous(workers,guard,fence);assertThat(jdbc.queryForObject("SELECT mode FROM ddip_management.coordinator",String.class)).isEqualTo("RECOVERY_ONLY");assertThatThrownBy(this::finish).isInstanceOf(RuntimeException.class);occupied();}
    @Test void artifactIdentityCollisionCannotComplete(){seeded();byte[] raw=SourceJson.canonical(SourceJson.object());jdbc.update("INSERT INTO ddip_management.artifacts(artifact_id,kind,product_id,contract_version,processor_revision,native_identity,storage_binding_id,relative_address,evidence_bytes,evidence_sha256,verified_at) VALUES (?,'CONTENT','content-intelligence',1,1,?,'content-CONTENT',?,?,?,clock_timestamp())",UUID.randomUUID(),"b".repeat(64),"v1/processor_revision=1/publication="+"b".repeat(64),raw,SourceJson.sha(raw));assertThatThrownBy(this::finish).hasMessage("RUNTIME_MISMATCH");assertThat(jdbc.queryForObject("SELECT active_attempt_id FROM ddip_management.coordinator",UUID.class)).isEqualTo(owner.attemptId());assertThat(jdbc.queryForObject("SELECT state FROM ddip_management.runs WHERE run_id=?",String.class,owner.runId())).isEqualTo("RUNNING");}
    @ParameterizedTest @ValueSource(strings={"PUBLISH_CONTENT","VERIFY_RESULT"}) void launchFailureHasNoChildAndCannotReauthorize(String stage){ready();fence=RssContentTestSupport.seed(jdbc,workers,guard,owner,stage);assertThat(jdbc.queryForObject("SELECT child_pid FROM ddip_management.stage_invocations WHERE stage=?",Long.class,stage)).isNull();RssContentTestSupport.cleanLaunchFailure(workers,guard,fence);assertThat(jdbc.queryForObject("SELECT state FROM ddip_management.stage_invocations WHERE stage=?",String.class,stage)).isEqualTo("FAILED");assertThatThrownBy(()->RssContentTestSupport.authorizeAgain(workers,guard,fence)).isInstanceOf(RuntimeException.class);occupied();}
    @ParameterizedTest @ValueSource(strings={"INSERT INTO ddip_management.stage_invocations","SET command_address=","SET state='VERIFIED',result_address="}) void lostStageAcknowledgmentNeverAuthorizesContent(String statement){ready();installLostCommit(statement);loseAck.set(true);assertThatThrownBy(()->RssContentTestSupport.seed(jdbc,workers,guard,owner)).hasMessage("MANAGEMENT_UNAVAILABLE");occupied();assertThat(jdbc.queryForObject("SELECT count(*) FROM ddip_management.stage_invocations WHERE stage='CHECK_INPUTS'",Integer.class)).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT count(*) FROM ddip_management.stage_invocations WHERE stage IN ('PUBLISH_CONTENT','VERIFY_RESULT')",Integer.class)).isZero();assertThatThrownBy(()->RssContentTestSupport.seed(jdbc,workers,guard,owner)).hasMessage("OWNERSHIP_LOST");occupied();}
    @Test void databaseInterruptionCannotRelease(){seeded();outage(true);try{assertThatThrownBy(this::finish).hasMessage("MANAGEMENT_UNAVAILABLE");}finally{outage(false);}occupied();}
    @ParameterizedTest @ValueSource(strings={"PUBLISH_CONTENT","VERIFY_RESULT"}) void ambiguousLaunchAuthorizationNeverBecomesReusable(String stage){ready();fence=RssContentTestSupport.seed(jdbc,workers,guard,owner,stage);RssContentTestSupport.ambiguous(workers,guard,fence);assertThat(jdbc.queryForObject("SELECT state FROM ddip_management.stage_invocations WHERE stage=?",String.class,stage)).isEqualTo("UNKNOWN");assertThatThrownBy(()->RssContentTestSupport.authorizeAgain(workers,guard,fence)).isInstanceOf(RuntimeException.class);occupied();assertThat(jdbc.queryForObject("SELECT count(*) FROM ddip_management.stage_invocations WHERE stage=?",Integer.class,stage)).isEqualTo(1);}
    @Test void missingMandatoryCheckpointCannotFinalize(){ready();fence=RssContentTestSupport.seed(jdbc,workers,guard,owner,"MISSING_FETCH");assertThatThrownBy(this::finish).hasMessage("OWNERSHIP_LOST");occupied();}
}
